import {COLORS,CATEGORY_LABELS,GROUP_LABELS,TRANSPORT_LABELS,STATUS_LABELS,PACK_COLORS,WEEKDAYS,esc,num,money,timeMin,minuteTime,durationText,sortEvents,dateRange,dateLabel,dayIndex,endMinute,costTotal,costSummary,costComposition,eventsForDate,getDayRoutes,getDayIssues,getTripIssues,makeUid,validateTrip,pruneRoutes,download,createICS} from './lib.js';
import {dayArt,brandArt,pickDayVisual,inferVisualKey} from './illustrations.js';
import {drawMap,disposeMap,navLink} from './map.js';
const STORAGE='seoul-family-travel-notebook-v1',MINUTE_HEIGHT=1.25;
let seed=null,trip=null,history=[],page='planning',selectedDate='',view=window.innerWidth<=700?'day':'week',lastSelectedDate='',mapMode='overview',routeCollapsed=false,previewId=null,packFilter='all',packQuery='',packCategory='all',costVisible=false,toastTimer=null,modalReturnFocus=null,gesture=null,mapTimer=null;
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const fmtNum=(v)=>v===null?'—':num(v);
const rawHtml=(str)=>esc(str??'').replace(/\n/g,'<br>');
const safeHttpUrl=url=>/^https?:\/\//i.test(String(url||''))?esc(url):null;
const currentEvents=()=>eventsForDate(trip,selectedDate);
const categoryStyle=c=>`--cat:${COLORS[c]||COLORS.other}`;
function notify(message){const el=$('#toast');if(!el)return;clearTimeout(toastTimer);el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
function saveDraft(){try{localStorage.setItem(STORAGE,JSON.stringify(trip));const d=$('#draftStatus');if(d){d.innerHTML='<span class="draft-dot"></span>本機草稿・已儲存';}}catch(err){notify('本機儲存失敗，請先匯出 JSON 備份。');console.error(err);}}
function changeTrip(mutator,message='變更已儲存'){history.push(structuredClone(trip));if(history.length>30)history.shift();mutator(trip);pruneRoutes(trip);trip.updatedAt=new Date().toISOString();saveDraft();renderAll();notify(message);}
function undo(){if(!history.length){notify('目前沒有可復原的變更');return;}trip=history.pop();saveDraft();renderAll();notify('已復原上一步，其他資料保持不變');}
function fmtCost(c){const t=costTotal(c);return t===null?'費用待填':money(t,c.currency||trip.currency);}
function timeSpan(e){return `${e.start} – ${minuteTime(endMinute(e))}`;}
function statusBadge(status){return `<span class="small-pill ${esc(status||'unknown')}">${STATUS_LABELS[status]||'待確認'}</span>`;}
function shortTags(e){return `${e.group!=='all'?`<span class="subtle-tag">${GROUP_LABELS[e.group]||esc(e.group)}</span>`:''}${e.locked?`<span class="subtle-tag">已預約・鎖定</span>`:''}`;}
function buildHeader(){const days=dateRange(trip.startDate,trip.endDate),sum=costSummary(trip);$('#tripTitle').textContent=trip.name;$('#tripMeta').innerHTML=`<span>${esc(trip.destination)}</span><i class="meta-divider"></i><span>${esc(dateLabel(trip.startDate))} — ${esc(dateLabel(trip.endDate))}</span><i class="meta-divider"></i><span>${trip.travellers.adults} 大 ${trip.travellers.children.length} 小</span>`;$('#tripDays').textContent=`${days.length} 天`;$('#tripPlaces').textContent=`${trip.events.length} 站`;
 $('#headerCost').textContent=costVisible?money(sum.sums.KRW||0,'KRW'):'••••••';$('#toggleCost').setAttribute('aria-pressed',String(costVisible));$('#toggleCost').setAttribute('aria-label',costVisible?'隱藏總花費':'顯示總花費');
 $('#brandArt').innerHTML=brandArt(trip);document.title=`${trip.name}｜旅行手帖`;
}
function renderAll(){if(!trip)return;disposeMap();buildHeader();$$('.tab-button').forEach(b=>{const yes=b.dataset.page===page;b.classList.toggle('active',yes);yes?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current');});const root=$('#appMain');if(page==='planning')renderPlanning(root);else if(page==='expenses')renderExpenses(root);else renderPacking(root);}
function renderPlanning(root){const es=currentEvents(),routes=getDayRoutes(trip,selectedDate),warn=getDayIssues(trip,selectedDate);
 root.innerHTML=`<section class="workspace" id="workspace">
 <div class="panel mappanel" id="mappanel">
  <header class="mapheading" id="mapheading"><h2 class="panel-title"><span class="panel-icon" aria-hidden="true">⌖</span>路線地圖 <small>ROUTE MAP</small></h2><span class="mapday">${esc(dateLabel(selectedDate))}</span></header>
  <div class="map-actions"><button type="button" class="outline-button ${mapMode==='route'?'active':''}" id="previewroute" data-action="map-mode" data-mode="route" aria-pressed="${mapMode==='route'}">路徑預覽</button><button type="button" class="outline-button ${mapMode==='overview'?'active':''}" id="fit" data-action="map-mode" data-mode="overview" aria-pressed="${mapMode==='overview'}">整天概覽</button><a class="naverlink" href="https://map.naver.com/" target="_blank" rel="noopener noreferrer">開啟 Naver Map ↗</a></div>
  <div class="mapstage"><div class="leaflet-map" id="mapCanvas" aria-label="當日地點地圖"></div><div class="map-legend"><i></i>${mapMode==='route'?'虛線為位置連線，非實際道路或車程':'地點依可用座標顯示；缺少地址者暫不標示'}</div></div>
  <div class="map-body-intro"><strong>當日 ${es.length} 個行程</strong><span>・</span><span>${routes.length} 段相鄰交通</span><span>・</span><span>${warn.length} 項時間提醒</span></div>
  <section class="routepanel ${routeCollapsed?'collapsed':''}" id="routepanel"><button type="button" class="route-heading" data-action="collapse-routes" aria-expanded="${!routeCollapsed}"><h3 class="panel-title"><span class="panel-icon">⇄</span>交通明細 <small>TRANSFERS</small></h3><span class="collapse-glyph">⌃</span></button><div class="route-content">${renderRoutes(routes)}</div></section>
 </div>
 <div class="panel calendarpanel" id="calendarpanel"><header class="calendarheading"><h2 class="panel-title"><span class="panel-icon" aria-hidden="true">▦</span>行事曆 <small>ITINERARY</small></h2><div class="toolbarbuttons"><button type="button" class="outline-button iconic" data-action="undo" aria-label="復原上一步" title="復原上一步">↶</button><button type="button" class="outline-button iconic primary-small" data-action="add-event" aria-label="新增行程" title="新增行程">＋</button></div></header>
 <div class="paneltoolbar" id="paneltoolbar"><span class="helper-external">當地時區：${esc(trip.timezone)}・未預約時段可編輯</span><div class="calendar-viewtoggle" id="calendar-viewtoggle" aria-label="切換日曆檢視"><button type="button" data-action="view" data-view="week" class="${view==='week'?'active':''}" aria-pressed="${view==='week'}">週視圖</button><button type="button" data-action="view" data-view="day" class="${view==='day'?'active':''}" aria-pressed="${view==='day'}">單日時間軸</button></div></div>
 <div class="date-header">${renderDateRail()}</div>
 ${warn.length?`<div class="day-alert" role="note"><span aria-hidden="true">⚠</span><div><strong>時間檢查：</strong>${esc(warn[0].text)}${warn.length>1?`<span>（另有 ${warn.length-1} 項）</span>`:''}</div><button type="button" data-action="show-issues">查看</button></div>`:''}
 <div class="calendar-main" id="calendar"><div id="calendarBody">${view==='week'?renderWeek():renderTimeline()}</div><div id="previewContainer">${renderPreview()}</div></div>
 </div></section>`;
 const target=$('#mapCanvas');mapTimer=setTimeout(()=>{if(page==='planning'&&target.isConnected)drawMap(target,es,routes,mapMode,(e)=>showPreview(e.id),trip);},10);
 afterDayRailUpdate();afterCalendarRender();
}
function renderRoutes(routes){if(!routes.length)return '<div class="no-routes">此日尚無相鄰路段。新增景點後會自動產生相鄰交通。</div>';
 let estimated=0,missing=0;const lis=routes.map(r=>{if(r.minutes===null)missing++;else estimated+=r.minutes;const cost=costTotal(r.cost),error=r.gap<0||(r.minutes!==null&&r.minutes>r.gap);return `<li class="route-item ${error?'route-alert':''}"><span class="route-symbol" aria-hidden="true">${modeGlyph(r.mode)}</span><div class="route-main"><strong>${esc(r.from.placeName||r.from.title)} → ${esc(r.to.placeName||r.to.title)}</strong><span>${TRANSPORT_LABELS[r.mode]||'待指定'}・${r.gap<0?'時段重疊':`空檔 ${r.gap} 分`}・${cost===null?'費用待填':money(cost,r.cost.currency)}</span></div><div class="route-min"><b>${r.minutes===null?'待估':`${r.minutes} 分`}</b><br><button type="button" data-action="edit-route" data-key="${esc(r.key)}">編輯</button></div></li>`;}).join('');
 return `<ul class="route-list">${lis}</ul><div class="route-summary summary"><span>已列路段 ${estimated} 分鐘（含估算）</span><span>｜</span><span>${missing} 段待估</span></div>`;}
function modeGlyph(mode){return ({walk:'↝',subway:'Ⓜ',train:'▥',shinkansen:'▥',bus:'▣',charter:'▰',taxi:'▰',car:'▱',plane:'✈',unknown:'？'})[mode]||'？';}
function renderDateRail(){const dates=dateRange(trip.startDate,trip.endDate),index=dates.indexOf(selectedDate);return `<div class="date-rail-top"><h3>${esc(dateLabel(selectedDate,true))} <span class="travel-year">${selectedDate.slice(0,4)} · 第 ${index+1} 天</span></h3><span class="travel-year">請點日期切換・插圖隨行程更新</span></div><div class="date-rail" style="--daycount:${dates.length}" id="dateRail"><div class="date-thumb" id="dateThumb" style="left:${((index+.5)/dates.length)*100}%">${dayArt(pickDayVisual(currentEvents()))}</div>${dates.map((d,i)=>`<button type="button" class="date-stop ${d===selectedDate?'selected':''}" data-action="select-date" data-date="${d}" aria-pressed="${d===selectedDate}"><span class="date-dot"></span><span class="date-week">${esc(dateLabel(d))}</span></button>`).join('')}</div>`;}
function afterDayRailUpdate(){if(!lastSelectedDate||lastSelectedDate===selectedDate)return;const t=$('#dateThumb');if(!t)return;const days=dateRange(trip.startDate,trip.endDate),a=days.indexOf(lastSelectedDate),b=days.indexOf(selectedDate);if(a<0||b<0){lastSelectedDate=selectedDate;return;}t.style.left=`${((a+.5)/days.length)*100}%`;requestAnimationFrame(()=>{t.classList.add('animating');t.style.left=`${((b+.5)/days.length)*100}%`;setTimeout(()=>t.classList.remove('animating'),560);});const bEl=$(`[data-action="select-date"][data-date="${selectedDate}"]`);bEl?.classList.add('date-bump');setTimeout(()=>bEl?.classList.remove('date-bump'),325);lastSelectedDate=selectedDate;}
function layoutWeekEvents(events){const arr=sortEvents(events).map(e=>({e,s:timeMin(e.start),end:endMinute(e),lane:0,size:1}));const groups=[];let group=[],maxEnd=-1;
 for(const item of arr){if(group.length && item.s>=maxEnd){groups.push(group);group=[];maxEnd=-1;}group.push(item);maxEnd=Math.max(maxEnd,item.end);}if(group.length)groups.push(group);
 for(const cluster of groups){const lanes=[];for(const item of cluster){let lane=lanes.findIndex(end=>end<=item.s);if(lane<0){lane=lanes.length;lanes.push(item.end);}else lanes[lane]=item.end;item.lane=lane;}for(const item of cluster)item.size=lanes.length;}return arr;}
function renderWeek(){const days=dateRange(trip.startDate,trip.endDate),es=trip.events;const first=Math.min(timeMin(trip.dayHours?.start||'07:00'),...es.map(e=>timeMin(e.start)));const last=Math.max(timeMin(trip.dayHours?.end||'22:00'),...es.map(endMinute));const start=Math.max(0,Math.floor(first/60)*60),end=Math.min(1440,Math.ceil(last/60)*60);const height=(end-start)*MINUTE_HEIGHT;const hourHeight=60*MINUTE_HEIGHT;
 const ticks=[];for(let t=start;t<=end;t+=60)ticks.push(`<span class="week-time-label" style="top:${(t-start)*MINUTE_HEIGHT}px">${minuteTime(t)}</span>`);
 const dayCols=days.map(d=>{const de=sortEvents(es.filter(e=>e.date===d)),items=layoutWeekEvents(de);return `<div class="week-day-column ${d===selectedDate?'chosen':''}" data-week-date="${d}" style="height:${height}px;--hour-height:${hourHeight}px">${items.map(({e,lane,size})=>{const top=(timeMin(e.start)-start)*MINUTE_HEIGHT,high=Math.max(39,e.durationMinutes*MINUTE_HEIGHT);const width=100/size,left=lane*width;const canDrag=!e.locked;return `<div class="week-event ${e.locked?'is-locked':''}" style="${categoryStyle(e.category)};top:${top}px;height:${high}px;left:calc(${left}% + 3px);width:calc(${width}% - 6px)" role="button" tabindex="0" data-event-id="${esc(e.id)}" data-week-event="1" title="單擊預覽／雙擊編輯${canDrag?'／按住 3 秒後拖移':''}"><div class="we-time">${e.start} ${e.locked?'◈':''}</div><div class="we-title">${esc(e.title)}</div><span class="we-tag">${GROUP_LABELS[e.group]||'全團'}</span>${canDrag?'<span class="resize-handle" data-resize="1" title="拖曳調整時長"></span>':''}</div>`;}).join('')}</div>`;}).join('');
 return `<div class="week-scroller" id="weekScroller"><div class="week-grid" style="--days:${days.length};--hour-height:${hourHeight}px"><div class="week-top-label">時間</div>${days.map((d,i)=>`<button type="button" class="week-top-label ${d===selectedDate?'chosen':''}" data-action="select-date" data-date="${d}"><strong>第 ${i+1} 天</strong>${dateLabel(d)}</button>`).join('')}<div class="week-time-column" style="height:${height}px">${ticks.join('')}</div>${dayCols}</div></div><div class="week-helper">單擊預覽・雙擊編輯・長按 3 秒拖移（已預約鎖定）；卡片底部把手可調整時長。週視圖可橫向捲動。</div>`;
}
function renderTimeline(){const es=currentEvents(),routes=getDayRoutes(trip,selectedDate),minStart=es.length?Math.floor(Math.min(...es.map(e=>timeMin(e.start)))/30)*30:timeMin(trip.dayHours.start),maxEnd=es.length?Math.ceil(Math.max(...es.map(endMinute))/30)*30:timeMin(trip.dayHours.end);const interval=maxEnd-minStart;const ticks=[];if(interval>0){const period=interval>800?120:60;for(let t=Math.ceil(minStart/period)*period;t<maxEnd;t+=period)ticks.push(`<span class="scale-tick" style="top:${((t-minStart)/interval)*100}%">${minuteTime(t)}</span>`);}
 const outById=new Map();routes.forEach(r=>{const a=outById.get(r.from.id)||[];a.push(r);outById.set(r.from.id,a);});
 const rows=es.map((e,i)=>{const outgoing=outById.get(e.id)||[];const next=outgoing.length===1?outgoing[0]:null;const previous=es.slice(0,i).reverse().find(x=>e.group==='all'||x.group==='all'||x.group===e.group);const transfer=e.category==='transport'?`<div class="transport-itinerary"><span class="transport-glyph">${modeGlyph(e.transportMode||'unknown')}</span><span>${esc(e.transportOrigin||previous?.placeName||'出發地待確認')}　→　${esc(e.placeName||'目的地待確認')}</span></div>`:'';const status=costTotal(e.cost)===null?'待填':STATUS_LABELS[e.cost.status]||'待確認';return `<div class="timeline-time-row" data-time-event="${esc(e.id)}" style="--strength:.5;--fade-dir:top"><div class="time-row-label">${e.start} — ${minuteTime(endMinute(e))}</div><div class="timeline-card" style="${categoryStyle(e.category)}" role="button" tabindex="0" data-event-id="${esc(e.id)}" data-timeline-event="1" aria-label="預覽 ${esc(e.title)}，可開啟編輯"><div class="timeline-card-head"><div class="label-group"><span class="category-tag">${CATEGORY_LABELS[e.category]||'其他'}</span>${shortTags(e)}</div><span class="time-duration">${durationText(e.durationMinutes)}</span></div><h4>${esc(e.title)}</h4>${transfer}<div class="card-address"><span aria-hidden="true">⌖</span> ${esc(e.placeName||e.address||'地點待補')}</div>${e.notes?`<p class="card-notes">${esc(e.notes)}</p>`:''}<div class="card-foot"><div><span class="cost-inline ${costTotal(e.cost)===null?'unknown':''}">${fmtCost(e.cost)}</span> <span class="status-note">${status}</span></div><div class="card-actions"><button class="textlink-btn" data-action="edit-event" data-id="${esc(e.id)}">編輯 ↗</button></div></div></div></div>${next&&next.minutes!==0?`<div class="mini-route"><span>${modeGlyph(next.mode)} ${TRANSPORT_LABELS[next.mode]}・${next.minutes===null?'時間待估':next.minutes+' 分鐘'} ${next.gap<0?'／重疊':''}</span><button type="button" data-action="edit-route" data-key="${esc(next.key)}">調整路段</button></div>`:''}`;}).join('');
 if(!es.length)return `<div class="day-empty"><strong>這一天還沒有安排</strong><span>可以新增景點、用餐或交通，日期插圖也會跟著改變。</span><button class="action main" data-action="add-event">＋ 新增行程</button></div>`;
 return `<section class="timelinepreview" id="timelinepreview"><div class="timeline-dates" aria-hidden="true">${dateLabel(selectedDate)}</div><div class="timeline-intro"><div><strong>第 ${dayIndex(trip,selectedDate)+1} 天・慢慢走，也走得剛剛好</strong><span>　${es.length} 筆安排</span></div><span>${minuteTime(minStart)} — ${minuteTime(maxEnd)}</span></div><div class="timeline-list" id="timeline-list"><aside class="day-time-scale" id="dayTimeScale" data-min="${minStart}" data-max="${maxEnd}" aria-label="當日起訖時間比例尺"><div class="scale-line"></div><span class="scale-tick" style="top:3%">${minuteTime(minStart)}</span>${ticks.join('')}<span class="scale-tick" style="top:97%">${minuteTime(maxEnd)}</span><div class="scale-focus" id="scaleFocus" aria-hidden="true"></div><div class="scale-now" id="scaleNow"><span id="nowLabel">現在</span></div></aside><div class="timeline-cards" id="timelineCards" role="region" aria-label="單日行程清單，可垂直捲動">${rows}</div></div></section>`;
}
function afterCalendarRender(){const timeCards=$('#timelineCards');if(timeCards){timeCards.addEventListener('scroll',updateTimelineFocus,{passive:true});timeCards.addEventListener('wheel',e=>{if(e.ctrlKey)return;e.preventDefault();timeCards.scrollTop+=Math.max(-32,Math.min(32,e.deltaY));updateTimelineFocus();},{passive:false});requestAnimationFrame(()=>{updateTimelineFocus();updateNowMarker();});}const week=$('#weekScroller');if(week)requestAnimationFrame(()=>{const col=$(`.week-day-column[data-week-date="${selectedDate}"]`);if(col&&window.innerWidth<600){week.scrollLeft=Math.max(0,col.offsetLeft-55);}});}
function updateTimelineFocus(){const sc=$('#timelineCards'),scale=$('#dayTimeScale'),dot=$('#scaleFocus');if(!sc||!scale||!dot)return;const rows=$$('.timeline-time-row',sc);if(!rows.length)return;const box=sc.getBoundingClientRect(),middle=box.top+box.height*.48;let closest=rows[0],dist=Infinity;rows.forEach(el=>{const b=el.getBoundingClientRect(),d=Math.abs((b.top+b.bottom)/2-middle);if(d<dist){dist=d;closest=el;}});if(sc.scrollTop<=5)closest=rows[0];if(sc.scrollTop+sc.clientHeight>=sc.scrollHeight-5)closest=rows[rows.length-1];
 rows.forEach(r=>{const b=r.getBoundingClientRect(),center=(b.top+b.bottom)/2,strength=Math.min(1,Math.abs(center-middle)/(box.height*.55));r.style.setProperty('--strength',r===closest?'0':strength.toFixed(3));r.style.setProperty('--fade-dir',center<middle?'bottom':'top');r.classList.toggle('timeline-current',r===closest);});
 const event=trip.events.find(e=>e.id===closest.dataset.timeEvent);if(event){const min=Number(scale.dataset.min),max=Number(scale.dataset.max),r=(timeMin(event.start)-min)/Math.max(1,max-min),offset=18+r*(scale.clientHeight-36);dot.style.top=`${Math.max(18,Math.min(scale.clientHeight-18,offset))}px`;}
}
function zoneNow(tz){try{const parts=new Intl.DateTimeFormat('en-GB',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const part=k=>parts.find(x=>x.type===k)?.value;return {date:`${part('year')}-${part('month')}-${part('day')}`,hour:part('hour'),minute:part('minute')};}catch{return null;}}
function updateNowMarker(){const scale=$('#dayTimeScale'),line=$('#scaleNow'),label=$('#nowLabel');if(!scale||!line)return;const n=zoneNow(trip.timezone);if(!n||n.date!==selectedDate){line.style.display='none';return;}const v=timeMin(`${n.hour}:${n.minute}`),min=Number(scale.dataset.min),max=Number(scale.dataset.max);if(v<min||v>max){line.style.display='none';return;}line.style.display='block';line.style.top=`${18+((v-min)/Math.max(1,max-min))*(scale.clientHeight-36)}px`;label.textContent=`${n.hour}:${n.minute}`;}
function renderPreview(){if(!previewId)return '';const e=trip.events.find(e=>e.id===previewId);if(!e||e.date!==selectedDate)return '';
 return `<div class="preview-drawer" id="eventPreview"><div class="preview-drawer-head"><div><span class="category-tag" style="${categoryStyle(e.category)}">${CATEGORY_LABELS[e.category]}</span> <span class="small-pill">${GROUP_LABELS[e.group]}</span><strong style="display:block;margin-top:4px">${esc(e.title)}</strong><div class="preview-note">${esc(e.date)} ${timeSpan(e)}・${durationText(e.durationMinutes)}</div></div><button type="button" class="textlink-btn" data-action="close-preview" aria-label="關閉預覽">關閉 ×</button></div><div class="preview-note">${esc(e.address||e.placeName||'尚未填地址')}<br>${rawHtml(e.notes||'')}</div><div class="drawer-actions"><button data-action="edit-event" data-id="${esc(e.id)}">編輯這筆</button><a href="${navLink(e)}" target="_blank" rel="noopener noreferrer" class="tiny-btn">在地圖查看 ↗</a></div></div>`;
}
function showPreview(id){previewId=id;const e=trip.events.find(e=>e.id===id);if(e&&e.date!==selectedDate){lastSelectedDate=selectedDate;selectedDate=e.date;renderPlanning($('#appMain'));return;}const container=$('#previewContainer');if(container)container.innerHTML=renderPreview();const r=$('#eventPreview');if(r&&view==='week')r.scrollIntoView({block:'nearest',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function showIssues(){const issues=getDayIssues(trip,selectedDate),critical=trip.checks.filter(x=>x.status!=='verified');showModal('時間與查證提醒',`<div class="modal-info">${esc(dateLabel(selectedDate))}・日程排列會根據相鄰路段判斷。交通未查證時不計為已確定可抵達。</div>${issues.length?issues.map(x=>`<div class="checkitem ${x.type==='danger'?'critical':'warning'}"><strong>${x.type==='danger'?'時間衝突':'時間緊湊'}</strong><p>${esc(x.text)}</p></div>`).join(''):'<p>目前沒有已知的時間重疊，但仍有待估路段。</p>'}<div class="form-section-title">旅程其他待確認事項</div>${critical.slice(0,6).map(x=>`<p><strong>${esc(x.title)}</strong>：${esc(x.detail)}</p>`).join('')}<div class="modal-actions"><button class="action" data-action="close-modal">關閉</button></div>`);}
function renderExpenses(root){const sum=costSummary(trip),s=costComposition(trip),totalForPie=Object.values(s).reduce((a,b)=>a+b,0),series=Object.entries(s).filter(([,v])=>v>0);let angle=0;const parts=series.map(([cat,v])=>{const a=angle;angle+=v/totalForPie*100;return `${COLORS[cat]||COLORS.other} ${a.toFixed(3)}% ${angle.toFixed(3)}%`;}).join(',');
 const days=dateRange(trip.startDate,trip.endDate);const rows=sortEvents(trip.events).map(e=>{const total=costTotal(e.cost),known=total!==null;return `<div class="expense-row"><div><strong>${esc(e.title)}</strong><small>${esc(dateLabel(e.date))}・${CATEGORY_LABELS[e.category]}${e.cost.items.length?`・${esc(e.cost.items.map(x=>`${x.label} ${x.quantity}${{perPerson:'人',perCar:'車',perGroup:'組'}[x.unit]||'份'}`).join('／'))}`:''}</small></div><span class="row-date">${esc(e.start)}</span><span class="row-amount">${known?money(total,e.cost.currency):'金額未填'}</span><div>${statusBadge(known?e.cost.status:'unknown')}<button type="button" data-action="edit-event" data-id="${esc(e.id)}">編輯</button></div></div>`}).join('');
 const checks=trip.checks.slice().sort((a,b)=>['critical','warning','info'].indexOf(a.level)-['critical','warning','info'].indexOf(b.level));
 root.innerHTML=`<section class="expensespage" id="expensespage"><header class="section-header"><div><h2>旅行費用總覽 <span class="travel-year">/ BUDGET</span></h2><p>以旅程資料計算；單價與數量明列，未知金額絕不當作零元。</p></div><button type="button" class="tiny-btn" data-action="export-json">備份預算 ↗</button></header><div class="expense-top"><div class="expense-totals"><h3>目前已列費用・幣別合計</h3><div class="totals-body"><div class="money-figure primary"><span>結算幣別 TWD・依目前匯率試算</span><strong>${sum.converted===null?'待設定匯率':money(sum.converted,'TWD')}</strong></div><div class="money-figure"><span>韓元 KRW 已知金額</span><strong>${money(sum.sums.KRW||0,'KRW')}</strong></div><div class="money-figure"><span>台幣 TWD 已知金額</span><strong>${money(sum.sums.TWD||0,'TWD')}</strong></div></div><form id="rate-form" class="exchange-box"><label for="fxInput">1 KRW ≒ TWD</label><input id="fxInput" inputmode="decimal" type="number" min="0" step="0.00001" placeholder="待輸入" value="${trip.exchangeRates?.KRW_TWD??''}"><button type="submit">更新匯率</button><span class="helper-external">手動輸入；只在合計後取整。</span></form><div class="cost-disclaimer">已列 ${sum.complete} 項（${sum.estimates} 項估算或情境）・未填 ${sum.notFilled} 個行程費用。${!sum.rateOK?'尚未設定韓元換算匯率。':''}</div></div>
 <div class="expense-chart"><h3>支出組成・類別占比</h3><div class="chart-inner"><div class="donut-chart" style="background:${series.length?`conic-gradient(${parts})`:'#f0ece4'}" role="img" aria-label="已列費用依類別占比；${series.map(([k,v])=>`${CATEGORY_LABELS[k]} ${Math.round(v/totalForPie*100)}%`).join('，')||'尚無費用'}"><div class="donut-center"><span>已列項目</span><strong>${series.length} 類</strong></div></div><div class="legend-list">${series.length?series.map(([cat,v])=>`<div class="legend-line"><i style="background:${COLORS[cat]||COLORS.other}"></i><span>${CATEGORY_LABELS[cat]||'其他'}</span><em>${Math.round(v/totalForPie*100)}%</em></div>`).join(''):'<span>尚無可計算金額</span>'}</div></div><div class="cost-disclaimer">${sum.rateOK?'圓餅以換算後的新台幣比較；所有金額皆為已填資料。':'匯率未設定前，圓餅僅比較各類別已填韓元金額；混用幣別需先設定匯率。'}</div></div></div>
 <div class="expense-bottom"><div class="expense-table"><h3>逐筆費用明細 <small>｜可直接編輯行程價格</small></h3><div class="expense-rows">${rows||'<div class="expense-empty">尚無行程</div>'}${Object.entries(trip.routeOverrides||{}).filter(([k,r])=>costTotal(r.cost)!==null && dateRange(trip.startDate,trip.endDate).some(d=>getDayRoutes(trip,d).some(x=>x.key===k))).map(([k,r])=>`<div class="expense-row"><div><strong>路段：${esc(k.replace('=>',' → '))}</strong><small>手動交通費用</small></div><span class="row-date">—</span><span class="row-amount">${money(costTotal(r.cost),r.cost.currency)}</span><div><button data-action="edit-route" data-key="${esc(k)}">編輯</button></div></div>`).join('')}</div></div><div class="checkpanel"><h3>假設／官方查證事項</h3>${checks.map(c=>`<div class="checkitem ${c.level} ${c.status==='verified'?'resolved':''}"><div class="checkitem-head"><strong>${esc(c.title)}</strong>${statusBadge(c.status==='verified'?'verified':'unknown')}</div><p>${esc(c.detail)}</p>${safeHttpUrl(c.source)?`<a href="${safeHttpUrl(c.source)}" target="_blank" rel="noopener noreferrer">官方來源 ↗</a>　`:''}<button type="button" data-action="toggle-check" data-id="${esc(c.id)}">${c.status==='verified'?'改回待確認':'標記已核對'}</button></div>`).join('')}</div></div></section>`;
}
function renderPacking(root){const packed=trip.packing.filter(p=>p.checked).length,total=trip.packing.length,percent=total?Math.round(packed/total*100):0;root.innerHTML=`<section class="packingpage" id="packingpage"><header class="section-header"><div><h2>攜帶用品清單 <span class="travel-year">/ PACKING</span></h2><p>冬季首爾・親子同行｜數量、備註、完成狀態都可修改。</p></div><button type="button" class="tiny-btn" data-action="add-pack">＋ 新增用品</button></header><div class="pack-summary"><div class="pack-progress-copy"><strong>${percent}% 已完成</strong><span>${packed} / ${total} 項已準備</span></div><div class="progress-bar" role="progressbar" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100" aria-label="用品準備進度"><div style="width:${percent}%"></div></div><span class="small-pill">${total-packed} 項待準備</span></div><div class="packing-controls"><label class="sr-only" for="packSearch">搜尋用品</label><input id="packSearch" type="search" placeholder="搜尋物品、備註…" value="${esc(packQuery)}"><label class="sr-only" for="packCategory">用品類別</label><select id="packCategory"><option value="all">所有類別</option>${uniquePackCategories().map(c=>`<option ${packCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select><label class="sr-only" for="packFilter">完成狀態</label><select id="packFilter"><option value="all" ${packFilter==='all'?'selected':''}>全部狀態</option><option value="todo" ${packFilter==='todo'?'selected':''}>未完成</option><option value="done" ${packFilter==='done'?'selected':''}>已完成</option></select></div><div id="packingList">${renderPackingGroups()}</div></section>`;}
const uniquePackCategories=()=>[...new Set(trip.packing.map(p=>p.category))];
function renderPackingGroups(){const query=packQuery.toLocaleLowerCase('zh-TW'),grouped=uniquePackCategories();const cards=grouped.map((c,i)=>{if(packCategory!=='all'&&packCategory!==c)return '';const items=trip.packing.filter(p=>p.category===c&&((packFilter==='all')||(packFilter==='done'&&p.checked)||(packFilter==='todo'&&!p.checked))&&(p.title+' '+p.notes).toLocaleLowerCase('zh-TW').includes(query));if(!items.length)return '';return `<div class="packing-group" style="--cat:${PACK_COLORS[i%PACK_COLORS.length]}"><h3>${esc(c)} <span>${trip.packing.filter(p=>p.category===c&&p.checked).length} / ${trip.packing.filter(p=>p.category===c).length}</span></h3><div class="packing-list">${items.map(p=>`<div class="packing-item ${p.checked?'checked':''}"><input type="checkbox" aria-label="${esc(p.title)} 已準備" data-pack-check="${esc(p.id)}" ${p.checked?'checked':''}><div class="packing-item-main"><strong>${esc(p.title)} <span class="subtle-tag">× ${Number(p.quantity)||1}</span></strong>${p.notes?`<small>${esc(p.notes)}</small>`:''}</div><button type="button" data-action="edit-pack" data-id="${esc(p.id)}" aria-label="編輯 ${esc(p.title)}">編輯</button></div>`).join('')}</div></div>`;}).filter(Boolean);return cards.length?`<div class="packing-grid">${cards.join('')}</div>`:'<div class="pack-noresults">沒有符合條件的用品，試試其他關鍵字或篩選。</div>';}
function showModal(title,content){modalReturnFocus=document.activeElement;$('#modalRoot').innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-head"><h2 id="modalTitle">${esc(title)}</h2><button class="modal-x" type="button" data-action="close-modal" aria-label="關閉視窗">×</button></header><div class="modal-content">${content}</div></section></div>`;requestAnimationFrame(()=>$('#modalBackdrop .modal-x')?.focus());}
function closeModal(){$('#modalRoot').innerHTML='';modalReturnFocus?.focus?.();modalReturnFocus=null;}
const field=(label,name,value,type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></label>`;
const choice=(name,value,opts)=>`<select name="${name}">${opts.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
function costRow(item={}){const id=item.id||makeUid('fee');return `<div class="costline-edit" data-cost-row data-item-id="${esc(id)}"><input class="cost-label" aria-label="費用名稱" data-cost-name placeholder="例如：門票" value="${esc(item.label||'')}"><select aria-label="計費單位" data-cost-unit>${[['perPerson','每人'],['perCar','每車'],['perGroup','全團／份']].map(([v,t])=>`<option value="${v}" ${v===item.unit?'selected':''}>${t}</option>`).join('')}</select><input aria-label="單價" data-cost-price type="number" min="0" step="0.01" placeholder="單價" value="${item.unitPrice??''}"><input aria-label="數量" data-cost-quantity type="number" min="0" step="1" placeholder="數量" value="${item.quantity??1}"><button type="button" data-action="delete-cost-row" aria-label="刪除費用明細">×</button></div>`;}
function readCostRows(form){return $$('[data-cost-row]',form).map(r=>{const raw=$('[data-cost-price]',r).value;return {id:r.dataset.itemId||makeUid('fee'),label:$('[data-cost-name]',r).value.trim()||'費用',unit:$('[data-cost-unit]',r).value,unitPrice:raw===''?null:Number(raw),quantity:Number($('[data-cost-quantity]',r).value)||0};}).filter(l=>l.unitPrice!==null||l.label!=='費用');}
function showEventForm(id){const original=id?trip.events.find(e=>e.id===id):null;if(id&&!original)return notify('找不到這筆行程');const e=original||{id:'',date:selectedDate,start:'10:00',durationMinutes:60,category:'spot',title:'',placeName:'',address:'',lat:null,lng:null,notes:'',group:'all',bookingStatus:'unverified',locked:false,cost:{currency:trip.currency,items:[],status:'unknown'},sourceUrl:''};
 const c=e.cost||{currency:trip.currency,items:[],status:'unknown'};showModal(original?'編輯行程・'+e.title:'新增行程',`<form id="eventForm" data-event-id="${esc(e.id)}"><div class="field-grid">
  <label class="field"><span>當地日期</span><input type="date" name="date" value="${e.date}" min="${trip.startDate}" max="${trip.endDate}" required></label>
  <label class="field"><span>類別</span>${choice('category',e.category,Object.entries(CATEGORY_LABELS))}</label>
  ${field('開始時間','start',e.start,'time','required')}${field('時長（分鐘）','duration',e.durationMinutes,'number','min="5" max="1440" step="5" required')}
  <label class="field"><span>參加組別</span>${choice('group',e.group,Object.entries(GROUP_LABELS))}</label>
  <label class="field"><span>預約狀態</span>${choice('bookingStatus',e.bookingStatus||'unverified',[['unverified','尚未確認預約'],['tentative','暫定時段'],['confirmed','已預約／已確認']])}</label>
  ${field('行程名稱','title',e.title,'text','required maxlength="110" class="span-all"')}
  ${field('地點顯示名稱','placeName',e.placeName,'text','maxlength="130"')}${field('完整地址／導航文字','address',e.address,'text','maxlength="240"')}
  <label class="field"><span>緯度（可空白）</span><input name="lat" type="number" step="any" min="-90" max="90" placeholder="未定位" value="${e.lat??''}"><span class="field-help">座標不確定時留空；不會產生虛假圖釘</span></label>
  <label class="field"><span>經度（可空白）</span><input name="lng" type="number" step="any" min="-180" max="180" placeholder="未定位" value="${e.lng??''}"></label>
  <label class="field span-all"><span>備註與可行性提醒</span><textarea name="notes" rows="3">${esc(e.notes)}</textarea></label>
  ${field('官方來源／預約連結','sourceUrl',e.sourceUrl||'','url','placeholder="https://..."')}
  <div class="checkbox-row"><input id="lockedInput" name="locked" type="checkbox" ${e.locked?'checked':''}><label for="lockedInput">鎖定已確認時段（禁止拖移／改時）</label></div>
 </div><div class="form-section-title">費用・每人／每車／全團分開計算</div><div class="field-grid">
  <label class="field"><span>計價幣別</span>${choice('currency',c.currency||trip.currency,[['KRW','韓元 KRW'],['TWD','新台幣 TWD'],['JPY','日圓 JPY'],['USD','美元 USD']])}</label>
  <label class="field"><span>查證狀態</span>${choice('costStatus',c.status||'unknown',Object.entries(STATUS_LABELS))}</label>
 </div><div id="costRowContainer">${(c.items||[]).map(costRow).join('')}</div><button class="action" type="button" data-action="add-cost-row">＋ 增加費用明細</button><p class="modal-info">沒有金額就留空；0 元只表示已確認免費。全團／每車單價不會與每人單價混淆。</p>
 <div class="modal-actions">${original?'<button class="action danger" type="button" data-action="delete-event">刪除行程</button>':''}<button class="action" type="button" data-action="close-modal">取消</button><button class="action main" type="submit">${original?'儲存變更':'建立行程'}</button></div></form>`);
}
function saveEvent(form){const fd=new FormData(form),id=form.dataset.eventId,original=id?trip.events.find(e=>e.id===id):null,date=fd.get('date'),start=fd.get('start'),duration=Number(fd.get('duration'));if(!dateRange(trip.startDate,trip.endDate).includes(date))return notify('行程日期必須在旅程範圍內');if(!Number.isFinite(timeMin(start))||duration<5||duration>1440||timeMin(start)+duration>1440)return notify('時間／時長有誤：請勿跨越當地午夜');const title=String(fd.get('title')||'').trim();if(!title)return notify('行程名稱不可空白');let locked=fd.has('locked'),bookingStatus=fd.get('bookingStatus');if(bookingStatus==='confirmed')locked=true;
 if(original?.locked && locked && (original.date!==date||original.start!==start||Number(original.durationMinutes)!==duration))return notify('這是已鎖定時段。請先取消鎖定再調整日期或時間。');
 if(original?.locked && !locked && !confirm(`「${original.title}」原本是鎖定時段，確定解除鎖定？`))return;
 const items=readCostRows(form),cost={currency:fd.get('currency'),items,status:items.length?fd.get('costStatus'):'unknown'};const newTitle=title!==original?.title;const placeChanged=!original||String(fd.get('placeName')||'')!==original.placeName||String(fd.get('address')||'')!==original.address;const latStr=String(fd.get('lat')||''),lngStr=String(fd.get('lng')||'');
 const obj={...(original||{}),id:original?.id||makeUid('evt'),date,start,durationMinutes:duration,category:fd.get('category'),title,placeName:String(fd.get('placeName')||'').trim(),address:String(fd.get('address')||'').trim(),locationId:placeChanged?null:original?.locationId||null,lat:latStr===''?null:Number(latStr),lng:lngStr===''?null:Number(lngStr),notes:String(fd.get('notes')||''),group:fd.get('group'),bookingStatus,locked,sourceUrl:String(fd.get('sourceUrl')||''),cost,visualKey:newTitle?inferVisualKey(title,fd.get('category')):original?.visualKey||inferVisualKey(title,fd.get('category')),visualPriority:newTitle?80:original?.visualPriority||80};
 closeModal();previewId=obj.id;changeTrip(t=>{const ix=t.events.findIndex(e=>e.id===obj.id);if(ix>=0)t.events[ix]=obj;else t.events.push(obj);},original?'已更新行程，相鄰路段、費用及日期插圖同步重算':'新增完成，已產生相鄰交通路段');if(obj.date!==selectedDate){lastSelectedDate=selectedDate;selectedDate=obj.date;renderAll();}
}
function deleteEvent(id){const ev=trip.events.find(x=>x.id===id);if(!ev)return;if(ev.locked&&!confirm(`「${ev.title}」已鎖定，確定仍要刪除？（可復原）`))return;if(!confirm(`刪除「${ev.title}」？其他行程不會變動，可用復原回上一步。`))return;closeModal();previewId=null;changeTrip(t=>t.events=t.events.filter(x=>x.id!==id),'已刪除行程；相鄰路段已重排，可按復原');}
function showTripSettings(){showModal('旅程設定・資料來源',`<form id="tripSettingsForm"><p class="modal-info">所有日期、天數、幣別、站點與插圖都讀取旅程資料。修改人數時會保留原費用明細數量，避免自行假設兒童票或團體折扣。</p><div class="field-grid">
 ${field('旅行名稱','name',trip.name,'text','required maxlength="110"')}${field('目的地','destination',trip.destination,'text','required')}
 ${field('開始日期','startDate',trip.startDate,'date','required')}${field('結束日期','endDate',trip.endDate,'date','required')}
 ${field('當地時區（IANA）','timezone',trip.timezone,'text','required placeholder="Asia/Seoul"')}${field('住宿地點','lodging',trip.lodging,'text')}
 ${field('成人數','adults',trip.travellers.adults,'number','min="0" max="200" required')}${field('兒童年齡（逗號分隔）','children',trip.travellers.children.join(', '),'text','placeholder="2.5, 8, 10"')}
 <label class="field"><span>主要金額幣別</span>${choice('currency',trip.currency,[['KRW','韓元 KRW'],['TWD','新台幣 TWD'],['JPY','日圓 JPY'],['USD','美元 USD']])}</label>
 <label class="field"><span>結算幣別</span>${choice('settlementCurrency',trip.settlementCurrency,[['TWD','新台幣 TWD']])}</label>
 ${field('每日可用起點','dayStart',trip.dayHours.start,'time','required')}${field('每日可用終點','dayEnd',trip.dayHours.end,'time','required')}
 </div><div class="modal-actions"><button class="action" type="button" data-action="close-modal">取消</button><button class="action main" type="submit">儲存旅程設定</button></div></form>`);}
function saveTripSettings(form){const fd=new FormData(form),start=fd.get('startDate'),end=fd.get('endDate'),days=dateRange(start,end),timez=String(fd.get('timezone')||'').trim();if(!days.length||days.length>45)return notify('請輸入合法日期範圍（最多 45 天）');try{new Intl.DateTimeFormat('en',{timeZone:timez});}catch{return notify('請輸入有效的當地時區，例如 Asia/Seoul');}const outside=trip.events.filter(e=>!days.includes(e.date));if(outside.length)return notify(`有 ${outside.length} 筆行程超出新日期範圍；請先調整它們以保留原內容。`);const a=Number(fd.get('adults'));if(!Number.isInteger(a)||a<0)return notify('成人數格式錯誤');const children=String(fd.get('children')||'').split(/[,，]/).map(x=>x.trim()).filter(Boolean).map(Number);if(children.some(x=>!Number.isFinite(x)||x<0||x>18))return notify('兒童年齡請填 0–18，以逗號隔開');const previous=JSON.stringify(trip.travellers),next=JSON.stringify({adults:a,children});if(timeMin(fd.get('dayStart'))>=timeMin(fd.get('dayEnd')))return notify('每日可用時間的起點必須早於終點');closeModal();changeTrip(t=>{t.name=String(fd.get('name')).trim();t.destination=String(fd.get('destination')).trim();t.startDate=start;t.endDate=end;t.timezone=timez;t.lodging=String(fd.get('lodging')||'');t.travellers={adults:a,children};t.currency=fd.get('currency');t.settlementCurrency=fd.get('settlementCurrency');t.dayHours={start:fd.get('dayStart'),end:fd.get('dayEnd')};if(previous!==next){const c=t.checks.find(x=>x.id==='check-prices');if(c)c.status='pending';}},previous!==next?'旅客資料已更新；原票價數量保留，請依年齡重新確認':'旅程設定已更新，日期列與插圖自動重建');}
function showRouteForm(key){const [fromId,toId]=key.split('=>'),from=trip.events.find(e=>e.id===fromId),to=trip.events.find(e=>e.id===toId);if(!from||!to)return notify('找不到交通路段');const existing=trip.routeOverrides[key]||{};const c=existing.cost||{currency:trip.currency,items:[],status:'unknown'};const first=c.items?.[0]||{};
 showModal('編輯交通・'+from.title+' → '+to.title,`<form id="routeForm" data-route-key="${esc(key)}"><p class="modal-info">只改這兩筆行程之間的路段。其他已手動確認路段與活動維持原樣。</p><div class="field-grid"><label class="field"><span>交通方式</span>${choice('mode',existing.mode||'unknown',Object.entries(TRANSPORT_LABELS))}</label>
 <label class="field"><span>車程／步行時間（分鐘）</span><input type="number" min="0" max="1440" step="1" name="minutes" placeholder="未查證，留空" value="${existing.minutes??''}"></label>
 <label class="field"><span>車程資料狀態</span>${choice('status',existing.status||'unknown',[['unknown','待確認'],['estimated','估算'],['verified','已查證']])}</label>
 <label class="field"><span>費用幣別</span>${choice('currency',c.currency||trip.currency,[['KRW','韓元 KRW'],['TWD','新台幣 TWD'],['JPY','日圓 JPY'],['USD','美元 USD']])}</label>
 ${field('交通費用單價','unitPrice',first.unitPrice,'number','min="0" step="0.01" placeholder="留空表示未知"')}
 <label class="field"><span>計價方式</span>${choice('unit',first.unit||'perGroup',[['perGroup','整段／全團'],['perPerson','每人'],['perCar','每車']])}</label>
 ${field('數量（人、車、團）','quantity',first.quantity??1,'number','min="0" step="1"')}
 <label class="field"><span>費用狀態</span>${choice('costStatus',c.status||'unknown',Object.entries(STATUS_LABELS))}</label>
 <label class="field span-all"><span>交通備註／估算依據</span><textarea name="notes">${esc(existing.notes||'')}</textarea></label></div><div class="modal-actions"><button class="action danger" type="button" data-action="reset-route" data-key="${esc(key)}">清除人工設定</button><button class="action" data-action="close-modal" type="button">取消</button><button class="action main" type="submit">儲存路段</button></div></form>`);
}
function saveRoute(form){const fd=new FormData(form),key=form.dataset.routeKey,min=String(fd.get('minutes')??''),rawPrice=String(fd.get('unitPrice')??'');if(min!==''&&(!Number.isFinite(Number(min))||Number(min)<0))return notify('時間不可為負數');const price=rawPrice===''?null:Number(rawPrice),quantity=Number(fd.get('quantity')||1);const cost={currency:fd.get('currency'),items:price===null?[]:[{id:'traffic-fee',label:'交通費',unit:fd.get('unit'),unitPrice:price,quantity}],status:price===null?'unknown':fd.get('costStatus')};const current=trip.routeOverrides[key]||{};const updated={...current,mode:fd.get('mode'),minutes:min===''?null:Number(min),status:fd.get('status'),notes:fd.get('notes'),cost};closeModal();changeTrip(t=>t.routeOverrides[key]=updated,'這一段交通已更新；相鄰時間與預算同步重算');}
function showPackForm(id){const existing=id?trip.packing.find(p=>p.id===id):null,p=existing||{title:'',category:uniquePackCategories()[0]||'其他',quantity:1,notes:''};showModal(existing?'編輯用品':'新增攜帶用品',`<form id="packForm" data-pack-id="${esc(id||'')}"><div class="field-grid">${field('用品名稱','title',p.title,'text','required maxlength="100"')}
 <label class="field"><span>分類</span>${choice('category',p.category,[...new Set([...uniquePackCategories(),'其他'])].map(c=>[c,c]))}</label>
 ${field('數量','quantity',p.quantity,'number','min="1" max="999" step="1" required')}<div></div><label class="field span-all"><span>備註</span><textarea name="notes">${esc(p.notes||'')}</textarea></label></div><div class="modal-actions">${existing?'<button type="button" class="action danger" data-action="delete-pack">刪除用品</button>':''}<button type="button" class="action" data-action="close-modal">取消</button><button type="submit" class="action main">儲存用品</button></div></form>`);}
function savePack(form){const fd=new FormData(form),id=form.dataset.packId,old=trip.packing.find(p=>p.id===id),title=String(fd.get('title')||'').trim(),quantity=Number(fd.get('quantity'));if(!title||!Number.isInteger(quantity)||quantity<1)return notify('用品名稱與數量不正確');const p={id:old?.id||makeUid('pack'),category:fd.get('category'),title,quantity,notes:String(fd.get('notes')||''),checked:old?.checked||false};closeModal();changeTrip(t=>{const i=t.packing.findIndex(x=>x.id===p.id);if(i<0)t.packing.push(p);else t.packing[i]=p;},'用品清單已更新');}
let suppressCardClickUntil=0;
function fabToggle(force){const fab=$('#fabButton'),menu=$('#fabMenu'),show=force??fab.getAttribute('aria-expanded')!=='true';fab.setAttribute('aria-expanded',String(show));fab.setAttribute('aria-label',show?'關閉旅程工具':'開啟旅程工具');menu.hidden=!show;if(show)menu.querySelector('button')?.focus();}
function setSelectedDate(date){if(date===selectedDate)return;if(!dateRange(trip.startDate,trip.endDate).includes(date))return;lastSelectedDate=selectedDate;selectedDate=date;previewId=null;renderAll();}
function handleAction(button){const action=button.dataset.action||button.dataset.tool;switch(action){
 case 'undo':undo();break;
 case 'add-event':case 'add':showEventForm();break;
 case 'trip-settings':showTripSettings();break;
 case 'edit-event':showEventForm(button.dataset.id);break;
 case 'close-preview':previewId=null;if($('#previewContainer'))$('#previewContainer').innerHTML='';break;
 case 'select-date':setSelectedDate(button.dataset.date);break;
 case 'view':if(view!==button.dataset.view){view=button.dataset.view;previewId=null;renderAll();}break;
 case 'map-mode':if(mapMode!==button.dataset.mode){mapMode=button.dataset.mode;renderAll();}break;
 case 'collapse-routes':routeCollapsed=!routeCollapsed;$('#routepanel')?.classList.toggle('collapsed',routeCollapsed);button.setAttribute('aria-expanded',String(!routeCollapsed));break;
 case 'edit-route':showRouteForm(button.dataset.key);break;
 case 'show-issues':showIssues();break;
 case 'close-modal':closeModal();break;
 case 'add-cost-row':$('#costRowContainer')?.insertAdjacentHTML('beforeend',costRow());break;
 case 'delete-cost-row':button.closest('[data-cost-row]')?.remove();break;
 case 'delete-event':deleteEvent($('#eventForm')?.dataset.eventId);break;
 case 'reset-route':if(confirm('清除這一段的人工車程與費用設定？其他路段不受影響。')){const key=button.dataset.key;closeModal();changeTrip(t=>delete t.routeOverrides[key],'已清除指定路段的人工設定');}break;
 case 'add-pack':showPackForm();break;
 case 'edit-pack':showPackForm(button.dataset.id);break;
 case 'delete-pack':{const id=$('#packForm')?.dataset.packId;if(!id)return;if(confirm('刪除這項用品？可按復原。')){closeModal();changeTrip(t=>t.packing=t.packing.filter(p=>p.id!==id),'已刪除用品，可按復原');}break;}
 case 'toggle-check':{const id=button.dataset.id;changeTrip(t=>{const c=t.checks.find(x=>x.id===id);if(c)c.status=c.status==='verified'?'pending':'verified';},'已更新查證狀態（由使用者手動確認）');break;}
 case 'export-json':download(JSON.stringify(trip,null,2),`${trip.id||'travel'}-draft.json`);notify('已匯出完整 JSON，可日後交由 AI 修改');break;
 case 'import-json':$('#jsonFileInput').click();break;
 case 'export-ics':download(createICS(trip),`${trip.id||'travel'}-${trip.timezone.split('/').pop()}.ics`,'text/calendar;charset=utf-8');notify(`已匯出 ${trip.events.length} 筆行程的 ICS（${trip.timezone}）`);break;
 case 'reset':if(confirm('要還原成上傳手冊的初始版本嗎？目前草稿會被替換；建議先匯出 JSON。可使用復原。')){changeTrip(t=>{Object.keys(t).forEach(k=>delete t[k]);Object.assign(t,structuredClone(seed));},'已還原初始旅程（可復原）');selectedDate=seed.startDate;renderAll();}break;
 }}
function pointerDown(ev){if(ev.button!==0)return;const handle=ev.target.closest('[data-resize]'),card=ev.target.closest('[data-week-event]');if(!card)return;const item=trip.events.find(e=>e.id===card.dataset.eventId);if(!item||item.locked)return;
 const isResize=Boolean(handle);gesture={id:item.id,card,pointerId:ev.pointerId,originX:ev.clientX,originY:ev.clientY,originStart:timeMin(item.start),originDuration:item.durationMinutes,originDate:item.date,mode:isResize?'resize':'hold',ready:isResize,dy:0,dx:0,timer:null};
 if(isResize){ev.preventDefault();card.classList.add('is-drag-ready');try{card.setPointerCapture(ev.pointerId);}catch{}}
 else gesture.timer=setTimeout(()=>{if(gesture?.id!==item.id||gesture?.mode!=='hold')return;gesture.mode='drag';gesture.ready=true;card.classList.add('is-drag-ready');try{card.setPointerCapture(ev.pointerId);}catch{};notify('可拖移行程了，放開將以 15 分鐘為單位更新');},3000);
}
function pointerMove(ev){if(!gesture||gesture.pointerId!==ev.pointerId)return;const g=gesture,gx=ev.clientX-g.originX,gy=ev.clientY-g.originY;g.dx=gx;g.dy=gy;
 if(g.mode==='hold' && (Math.abs(gy)>9||Math.abs(gx)>9)){clearTimeout(g.timer);g.card.classList.remove('is-drag-ready');gesture=null;return;}
 if(!g.ready)return;if(g.mode==='resize'){const val=Math.max(15,Math.min(1440,Math.round((g.originDuration+gy/MINUTE_HEIGHT)/15)*15));g.previewDuration=val;g.card.style.height=`${Math.max(39,val*MINUTE_HEIGHT)}px`;g.card.classList.add('is-dragging');}else{
  g.previewMinutes=Math.round(gy/MINUTE_HEIGHT/15)*15;
  g.card.style.transform=`translate(${gx}px,${gy}px)`;g.card.classList.add('is-dragging');
 }
 ev.preventDefault();
}
function pointerEnd(ev){const g=gesture;if(!g||g.pointerId!==ev.pointerId)return;clearTimeout(g.timer);gesture=null;g.card.classList.remove('is-drag-ready','is-dragging');g.card.style.transform='';g.card.style.height='';if(!g.ready)return;
 const item=trip.events.find(e=>e.id===g.id);if(!item||item.locked)return;
 if(g.mode==='resize'){const duration=g.previewDuration||g.originDuration;const valid=Math.min(duration,1440-g.originStart);if(valid!==g.originDuration){suppressCardClickUntil=Date.now()+500;changeTrip(t=>{const ev=t.events.find(x=>x.id===g.id);if(ev)ev.durationMinutes=valid;},`已調整時長為 ${durationText(valid)}，相關時間提醒同步更新`);}return;}
 if(Math.abs(g.dy)<7 && Math.abs(g.dx)<7)return;
 const src=g.card.closest('.week-day-column'),colWidth=src?.getBoundingClientRect().width||130,days=dateRange(trip.startDate,trip.endDate),originalIndex=days.indexOf(g.originDate),shift=Math.round(g.dx/colWidth),newIndex=Math.max(0,Math.min(days.length-1,originalIndex+shift)),newDate=days[newIndex],minutes=Math.max(0,Math.min(1439-item.durationMinutes,g.originStart+(g.previewMinutes||0))),newStart=minuteTime(Math.round(minutes/15)*15);
 if(item.date===newDate&&item.start===newStart)return;suppressCardClickUntil=Date.now()+600;lastSelectedDate=selectedDate;selectedDate=newDate;changeTrip(t=>{const e=t.events.find(x=>x.id===g.id);if(e){e.date=newDate;e.start=newStart;}},`已移至 ${dateLabel(newDate)} ${newStart}；交通與費用已重算`);
}
async function importJsonFile(file){if(!file)return;try{const content=await file.text(),parsed=validateTrip(JSON.parse(content));if(!confirm(`匯入「${parsed.name}」？將替換目前草稿（${parsed.events.length} 筆），建議先另存 JSON。可用復原上一步。`))return;history.push(structuredClone(trip));trip=parsed;selectedDate=trip.startDate;lastSelectedDate='';previewId=null;page='planning';saveDraft();renderAll();notify('匯入成功：地圖、日期列、插圖、費用已根據新旅程重建');}catch(err){console.error(err);notify('匯入失敗：'+err.message);}}
function bindGlobalHandlers(){document.addEventListener('click',e=>{
 const pageButton=e.target.closest('[data-page]');if(pageButton){page=pageButton.dataset.page;fabToggle(false);renderAll();return;}
 if(e.target.closest('#toggleCost')){costVisible=!costVisible;buildHeader();return;}
 if(e.target.closest('#fabButton')){fabToggle();return;}
 const tool=e.target.closest('[data-tool]');if(tool){fabToggle(false);handleAction(tool);return;}
 const action=e.target.closest('[data-action]');if(action){handleAction(action);return;}
 if(e.target.id==='modalBackdrop')closeModal();
 const card=e.target.closest('[data-week-event],[data-timeline-event]');if(card&&Date.now()>suppressCardClickUntil){showPreview(card.dataset.eventId);return;}
 if(!e.target.closest('#fabWrap')&&$('#fabButton').getAttribute('aria-expanded')==='true')fabToggle(false);
 });
 document.addEventListener('dblclick',e=>{const card=e.target.closest('[data-week-event]');if(card){e.preventDefault();showEventForm(card.dataset.eventId);}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modalBackdrop'))closeModal();else if($('#fabButton').getAttribute('aria-expanded')==='true')fabToggle(false);return;}
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.closest('input,textarea,[contenteditable]')){e.preventDefault();undo();return;}
 if(e.key==='Tab'&&$('#modalBackdrop')){const box=$('#modalBackdrop .modal'),list=$$('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[href]',box).filter(x=>!x.hidden&&x.offsetParent!==null);if(list.length){const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
 if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-week-event],[data-timeline-event]')){e.preventDefault();if(e.key==='Enter')showEventForm(e.target.dataset.eventId);else showPreview(e.target.dataset.eventId);}
 });
 document.addEventListener('pointerdown',pointerDown);document.addEventListener('pointermove',pointerMove);document.addEventListener('pointerup',pointerEnd);document.addEventListener('pointercancel',pointerEnd);
 document.addEventListener('change',e=>{const input=e.target;if(input.matches('[data-pack-check]')){const id=input.dataset.packCheck,value=input.checked;changeTrip(t=>{const p=t.packing.find(x=>x.id===id);if(p)p.checked=value;},value?'已勾選這項用品':'已改回未完成');}
 if(input.id==='packFilter'){packFilter=input.value;$('#packingList').innerHTML=renderPackingGroups();}if(input.id==='packCategory'){packCategory=input.value;$('#packingList').innerHTML=renderPackingGroups();}
 });
 document.addEventListener('input',e=>{if(e.target.id==='packSearch'){packQuery=e.target.value;$('#packingList').innerHTML=renderPackingGroups();}});
 document.addEventListener('submit',e=>{if(e.target.id==='eventForm'){e.preventDefault();saveEvent(e.target);}if(e.target.id==='routeForm'){e.preventDefault();saveRoute(e.target);}if(e.target.id==='packForm'){e.preventDefault();savePack(e.target);}if(e.target.id==='tripSettingsForm'){e.preventDefault();saveTripSettings(e.target);}if(e.target.id==='rate-form'){e.preventDefault();const raw=$('#fxInput')?.value.trim()||'',rate=raw===''?null:Number(raw);if(rate!==null && (!(rate>0)||!Number.isFinite(rate)))return notify('匯率需為正數，或留空表示尚未確認');changeTrip(t=>{t.exchangeRates ||= {};t.exchangeRates.KRW_TWD=rate;},rate===null?'已保留匯率空值':'已依新匯率合計，最後才四捨五入');}
 });
 $('#jsonFileInput').addEventListener('change',async e=>{await importJsonFile(e.target.files?.[0]);e.target.value='';});
 window.addEventListener('resize',()=>{if(page==='planning'){updateTimelineFocus();updateNowMarker();}});
 window.addEventListener('load',()=>{if(page==='planning'&&window.L){const es=currentEvents();drawMap($('#mapCanvas'),es,getDayRoutes(trip,selectedDate),mapMode,(x)=>showPreview(x.id),trip);}});
}
async function start(){bindGlobalHandlers();try{const r=await fetch('./data/seoul2026.json');if(!r.ok)throw new Error('找不到初始旅程資料');seed=validateTrip(await r.json());let draft=null;try{draft=localStorage.getItem(STORAGE);if(draft)draft=validateTrip(JSON.parse(draft));}catch(err){console.warn('本機草稿讀取失敗',err);draft=null;}
 trip=draft||structuredClone(seed);selectedDate=trip.startDate;lastSelectedDate='';renderAll();setInterval(updateNowMarker,15000);if(draft)notify('已載入上次儲存的本機旅程草稿');}catch(err){console.error(err);$('#appMain').innerHTML=`<section class="empty-view"><h2>旅程資料尚未載入</h2><p>${esc(err.message)}。請以本機 HTTP 伺服器啟動，不要直接用 file:// 開啟。</p><p>在專案資料夾執行：<code>python3 -m http.server 4173</code>，再開啟 <code>http://localhost:4173</code>。</p></section>`;}}
start();
